const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',route:'M6 3a3 3 0 1 0 0 6 3 3 0 0 0 0-6Zm12 12a3 3 0 1 0 0 6 3 3 0 0 0 0-6ZM9 6h7a4 4 0 0 1 0 8H8a3 3 0 0 0 0 6h7',bus:'M5 17h14V5c0-3-14-3-14 0Zm0-7h14M7 17v3m10-3v3M8 14h.01M16 14h.01',bell:'M4 17h16l-2-3V9a6 6 0 0 0-12 0v5Zm6 4h4',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',book:'M12 5C8 2 4 3 2 4v15c4-2 7-1 10 1 3-2 6-3 10-1V4c-2-1-6-2-10 1Zm0 0v15',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',pin:'M19 9c0 6-7 12-7 12S5 15 5 9a7 7 0 0 1 14 0ZM15 9a3 3 0 1 1-6 0 3 3 0 0 1 6 0',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 7v5l3 2',card:'M3 5h18v14H3ZM3 9h18M6 15h4',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Zm-2 5 6 6',check:'m5 12 4 4L19 6',plus:'M12 4v16M4 12h16',close:'m6 6 12 12M6 18 18 6',chart:'M4 20V10m8 10V4m8 16v-7',alert:'m12 3 10 18H2ZM12 9v5m0 3h.01',leaf:'M20 3C4 2 2 10 6 16c6 6 15-1 14-13ZM4 21 15 10',swap:'m7 3-4 4 4 4M3 7h16m-2 6 4 4-4 4M5 17h16',star:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z',coffee:'M4 8h13v8a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5Zm13 1h2a3 3 0 0 1 0 6h-2M7 2v3m5-3v3'};
const icon=(n)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.bus}"/></svg>`;
const $=s=>document.querySelector(s), money=n=>'S/ '+Number(n).toFixed(2), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stations=['Naranjal','Tomás Valle','UNI','Caquetá','España','Central','Estadio Nacional','Canaval y Moreyra','Angamos','Matellini'];
const initial=()=>({cards:[{id:1,name:'Mi tarjeta universitaria',type:'Universitaria',digits:'4829',balance:24.50},{id:2,name:'Mi tarjeta general',type:'General',digits:'7310',balance:12}],selected:1,transactions:[],active:null,read:[],done:[],alerts:false,name:'Bris'});
let data;try{data=JSON.parse(localStorage.getItem('metro-demo-v1'))||initial()}catch{data=initial()}
let page='home',origin='Naranjal',destination='Central',preference='changes',choice=0,showRoutes=false,station='Naranjal',direction='Sur',allBuses=false,period='week',noticeFilter='all',depart='18:00',flex='45',lastRoute=null;
const save=()=>{try{localStorage.setItem('metro-demo-v1',JSON.stringify(data))}catch{toast('No se pudo guardar en este navegador.')}};
const card=()=>data.cards.find(c=>c.id===data.selected)||data.cards[0];
const fare=()=>card().type==='Universitaria'?1.60:3.20;
const navs=[['home','home','Inicio'],['plan','route','Planificar'],['trip','bus','Mi viaje'],['tutorials','book','Tutoriales'],['notices','bell','Avisos'],['profile','user','Mi perfil']];
const title=p=>navs.find(n=>n[0]===p)?.[2]||({smart:'Evita la hora punta',trip:'Mi viaje',live:'Rutas y horarios',station:'Detalle de estación',guide:'Guía de viaje'}[p]||'Inicio');
function go(p){if(p==='plan'&&['home','station','smart'].includes(page)){planNetwork='metro';showRoutes=false}page=p;render();window.scrollTo({top:0,behavior:'instant'})}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function shell(){const brand=`<div class="brand"><img class="brand-logo" src="assets/favicon.png" alt=""><div>Chapa tu Bus<small>PLANIFICA · VIAJA · LLEGA</small></div></div>`;$('#sidebar').innerHTML=brand+`<div class="navs">${navs.map(([p,i,n])=>`<button class="nav-item ${page===p?'active':''}" onclick="go('${p}')">${icon(i)}${n}${p==='notices'?'<span class="pill teal">'+(2-data.read.length)+'</span>':''}</button>`).join('')}</div><div class="side-bottom"><span class="pill green">● MODO DEMOSTRACIÓN</span><p>Explora, planifica y prueba.<br>Tu próximo viaje empieza aquí.</p><button class="text-btn" onclick="about()">Sobre este prototipo ${icon('arrow')}</button></div>`;$('#header').innerHTML=`<div class="header-path">Tu movilidad <span style="margin-left:14px">/</span><b>${title(page)}</b></div><div class="mobile-brand">${brand}</div><div class="row header-actions"><span class="pill green header-desktop">${['live','plan','trip'].includes(page)?'Rutas de referencia':'● Datos simulados'}</span><button class="icon-btn" aria-label="Avisos" onclick="go('notices')">${icon('bell')}</button><button class="avatar" aria-label="Abrir perfil" onclick="go('profile')">${esc(data.name.slice(0,2).toUpperCase())}</button></div>`;$('#bottom').innerHTML=navs.filter(n=>n[0]!=='notices').map(([p,i,n])=>`<button class="${page===p?'active':''}" onclick="go('${p}')">${icon(i)}${n}</button>`).join('')}
const heading=(a,b,back=false)=>`<div class="heading">${back?'<button class="text-btn" style="margin-bottom:16px" onclick="go(\'home\')">'+icon('back')+' Inicio</button>':''}<h1>${a}</h1><p>${b}</p></div>`;
function wallet(){return `<div class="wallet"><div class="row between"><span class="row">${icon('card')}<small>Mi tarjeta</small></span><select aria-label="Seleccionar tarjeta" onchange="selectCard(this.value)">${data.cards.map(c=>`<option value="${c.id}" ${c.id===card().id?'selected':''}>${esc(c.type)} · ${esc(c.digits)}</option>`).join('')}</select></div><div style="margin-top:17px"><small>Saldo disponible · simulado</small><div class="balance"><span>S/</span>${card().balance.toFixed(2)}</div></div><div class="row between"><small>•••• ${esc(card().digits)}</small><button class="text-btn" onclick="recharge()">${icon('plus')} Recargar</button></div></div>`}
function selectCard(id){data.selected=Number(id);save();render()}
const buslist=()=>[{id:'B',min:3,level:'Alta',cls:'red',stop:true},{id:'B',min:7,level:'Media',cls:'amber',stop:true},{id:'EX',min:5,level:'Baja',cls:'green',stop:false},{id:'A',min:10,level:'Baja',cls:'green',stop:true}];
function buses(limit=4){return buslist().filter(b=>allBuses||b.stop).slice(0,limit).map(b=>`<button class="bus-row" onclick="busDetail('${b.id}',${b.stop})"><span class="bus-letter">${b.id}</span><span><strong>${b.id==='EX'?'Expreso':'Regular '+b.id} · ${direction==='Sur'?'Matellini':'Naranjal'}</strong><p><span class="pill ${b.cls}">● Ocupación ${b.level.toLowerCase()}</span> ${!b.stop?'<span class="pill">No se detiene</span>':''}</p></span><span class="bus-time">${b.min}<small> min</small></span></button>`).join('')}
function bars(values,labels,selected=-1){return `<div class="chart-bars">${values.map((v,i)=>`<div class="chart-col ${v<45?'good':''} ${i===selected?'selected':''}"><i style="height:${v}%" title="${labels[i]}: demanda ${v}%"></i><span>${labels[i]}</span></div>`).join('')}</div>`}
function smartBox(){return `<div class="card smart home-smart"><div class="row between"><span class="row"><span class="smart-icon">${icon('spark')}</span><h3>Evita la hora punta</h3></span></div><div class="smart-time">Sal a las 18:40 <span style="font-size:20px">↗</span></div><p>Un rato más en la biblioteca.<br>Una espera más corta en la estación.</p>${bars([45,75,95,78,35,25],['17:30','18:00','18:15','18:30','18:40','19:00'],4)}<div class="row between" style="margin-top:20px"><span class="small" style="color:#37805e">↓ 12 min menos de espera*</span><button class="text-btn" onclick="go('smart')">Ver plan ${icon('arrow')}</button></div><div class="muted" style="font-size:9px;margin-top:13px">*Escenario ilustrativo, no es una predicción real.</div></div>`}
function heroArt(){return `<svg class="hero-art" viewBox="0 0 240 210"><path d="M220-15v70q0 30-30 30H120q-35 0-35 35v100" fill="none" stroke="#c5ded0" stroke-width="30"/><path d="M220-15v70q0 30-30 30H120q-35 0-35 35v100" fill="none" stroke="#eef6ee" stroke-width="2" stroke-dasharray="6 7"/><g transform="translate(135,59) rotate(-12)"><rect width="70" height="40" rx="10" fill="#548e76"/><rect x="10" y="7" width="48" height="15" rx="4" fill="#cfe3d7"/><circle cx="15" cy="39" r="6" fill="#224b42"/><circle cx="55" cy="39" r="6" fill="#224b42"/></g><circle cx="86" cy="170" r="10" fill="#e7f2ee" stroke="#61967e" stroke-width="4"/></svg>`}
function home(){return heading(`Buen día, ${esc(data.name)} <span style="font-weight:400">☀</span>`,'Tu ciudad se mueve. Tú eliges cómo.')+`${data.active?`<button class="banner full row between" onclick="go('trip')">${icon('bus')} Tienes un viaje en curso a ${esc(data.active.destination)} ${icon('arrow')}</button><br>`:''}<div class="grid home-grid"><div class="stack home-left"><div class="hero home-hero">${heroArt()}<div><span class="eyebrow" style="color:#618b78">VIAJA CON MÁS CALMA</span><h2 style="margin-top:10px">Menos vueltas.<br>Más tiempo para ti.</h2><p>Encuentra tu ruta y adelántate a la espera.</p></div><button class="search-btn" onclick="go('plan')">${icon('search')} ¿A dónde vamos hoy? ${icon('arrow')}</button></div><section class="card home-station"><div class="station-top"><div class="row between"><span class="eyebrow muted">TU ESTACIÓN</span><button class="text-btn" onclick="go('station')">Ver estación ${icon('arrow')}</button></div><div class="row between" style="margin-top:13px"><select class="station-select" aria-label="Tu estación" onchange="station=this.value;origin=this.value;render()">${stationOptions(station)}</select><span class="pill amber">● Afluencia media</span></div><div class="muted small" style="margin-top:7px">Hacia ${direction==='Sur'?'Matellini':'Naranjal'} · Sentido ${direction.toLowerCase()}</div></div><div class="section-title" style="margin:20px 0 0"><h3>Próximos buses</h3><span class="muted" style="font-size:10px">Llegadas de ejemplo</span></div>${buses(2)}<div class="wait"><span class="row" style="gap:6px">${icon('clock')} Espera para abordar</span><strong>6–9 min</strong></div></section><div class="quick home-quick"><button onclick="go('live')">${icon('bus')} Rutas y horarios</button><button onclick="go('profile')">${icon('chart')} Mis gastos</button><button onclick="go('tutorials')">${icon('book')} Aprende a viajar</button></div></div><div class="stack home-right"><div class="home-wallet">${wallet()}</div>${smartBox()}<section class="card home-tutorial"><div class="section-title"><h3>Tu primera parada</h3><button class="text-btn" onclick="go('tutorials')">Ver guías ${icon('arrow')}</button></div>${tutorialPreview(0)}${tutorialPreview(1)}</section></div></div>`}
const stationOptions=(s)=>stations.map(n=>`<option ${n===s?'selected':''}>${n}</option>`).join('');
function calcRoute(){let a=stations.indexOf(origin),b=stations.indexOf(destination),stops=Math.abs(a-b);return {duration:12+stops*4,direction:b>a?'Sur':'Norte',stops}}
function plan(){return referencePlan()}
function searchRoutes(){if(origin===destination)return toast('Elige una estación de destino diferente.');showRoutes=true;choice=0;render()}
function openTrip(){lastRoute=findJourneys(origin,destination,preference)[choice];if(lastRoute)go('trip')}
function trip(){const r=data.active||lastRoute;if(r?.legs)return referenceTrip(r);if(!r)return heading('Aún no tienes un viaje','Elige tu destino para comenzar.')+'<button class="primary" onclick="go(\'plan\')">Planificar viaje</button>';return heading(data.active?'Tu viaje está en marcha':'Tu viaje a '+esc(r.destination),`${esc(r.origin)} → ${esc(r.destination)} · Recorrido simulado`)+`<div class="grid"><section class="card"><div class="row between"><span class="route-min">${r.duration} <small>min aprox.</small></span><span class="pill teal">${r.choice?'1 transbordo':'Sin transbordos'}</span></div><div class="banner spaced row">${icon('bus')} ${r.choice?'Regular A → Regular C':'Regular B'} · Sentido ${r.direction}</div><div class="timeline">${[[`Camina hasta ${r.origin}`,'2 min a pie · acceso referencial'],['Aborda '+(r.choice?'Regular A':'Regular B'),'Espera estimada: 6–9 min'],...(r.choice?[['Cambia a Regular C','Transbordo de demostración en estación intermedia']]:[]),[`Baja en ${r.destination}`,'Recibirás un aviso si activas la alerta'],['Continúa hasta tu destino','2 min a pie']].map(([a,b],i)=>`<div class="step"><span class="step-num">${i+1}</span><div><strong>${a}</strong><p>${b}</p></div></div>`).join('')}</div><label class="row"><input class="switch" type="checkbox" ${data.alerts?'checked':''} onchange="data.alerts=this.checked;save();toast(this.checked?'Alerta de demostración activada':'Alerta desactivada')"> Avisarme antes de bajar (dentro de la app)</label></section><div class="stack">${mapSvg(true)}<section class="card">${data.active?`<span class="pill green">${icon('check')} Pasaje registrado</span><p>${money(data.active.cost)} descontados de ${esc(data.active.cardName)}.</p><button class="primary full" onclick="finishTrip()">Finalizar viaje ${icon('check')}</button><button class="text-btn spaced" onclick="go('profile')">Ver movimiento y saldo</button>`:`<h3>Elige tu tarjeta</h3><select class="spaced" aria-label="Tarjeta de pago" onchange="selectCard(this.value)">${data.cards.map(c=>`<option value="${c.id}" ${c.id===card().id?'selected':''}>${esc(c.name)} · ${money(c.balance)}</option>`).join('')}</select><div class="row between spaced"><span>Pasaje simulado${r.choice?' · 2 abordajes':''}</span><strong>${money(fare()*(r.choice+1))}</strong></div><p class="small muted">Al iniciar se descontará una sola vez del saldo de ejemplo y aparecerá en tus gastos. No es un pago real.</p><button class="primary full" onclick="startTrip()">Iniciar ruta ${icon('arrow')}</button>`}</section></div></div>`}
function startTrip(){if(data.active){go('trip');return}if(!lastRoute)return;const c=card(),cost=Math.round(fare()*(lastRoute.legs?.length||(lastRoute.choice+1))*100)/100;if(c.balance<cost){toast('Saldo insuficiente. Recarga tu tarjeta de demostración.');return}c.balance=Math.round((c.balance-cost)*100)/100;data.active={...lastRoute,cost,cardName:c.name,id:Date.now()};data.transactions.unshift({id:Date.now(),type:'trip',amount:cost,date:new Date().toISOString(),label:lastRoute.origin+' → '+lastRoute.destination,card:c.name});save();render();toast('Viaje iniciado · '+money(cost)+' registrados en gastos')}
function finishTrip(){if(!data.active)return;data.active=null;save();go('profile');toast(data.alerts?'Llegaste a tu destino. ¡Buen viaje!':'Viaje finalizado. Tu gasto está guardado.')}
function mapSvg(active){return `<div class="map"><span class="map-label">${active?'● Seguimiento simulado':'ESQUEMA DEL CORREDOR'} · Sin GPS</span><svg viewBox="0 0 440 400" role="img" aria-label="Mapa esquemático de estaciones del Metropolitano"><defs><pattern id="blocks" width="70" height="58" patternUnits="userSpaceOnUse" patternTransform="rotate(-18)"><rect x="7" y="6" width="54" height="43" rx="7" fill="#e5ebe1"/></pattern></defs><rect width="440" height="400" fill="url(#blocks)"/><path d="M0 345Q75 290 90 370L135 400H0" fill="#cce3df"/><path d="M30 70Q130 130 160 210T420 340" fill="none" stroke="#fff" stroke-width="21"/><path d="M150 20v75l35 45v100l40 55v100" fill="none" stroke="#fff" stroke-width="18"/><path d="M150 55v40l35 45v100l40 55v65" fill="none" stroke="#0b5aa8" stroke-width="6" stroke-linecap="round"/>${[['Naranjal',150,65],['Tomás Valle',150,100],['UNI',185,153],['Caquetá',185,210],['España',204,266],['Central',225,318],['Matellini',225,360]].map(([n,x,y])=>`<circle cx="${x}" cy="${y}" r="6" fill="white" stroke="#0b5aa8" stroke-width="3"/><text x="${x+16}" y="${y+4}" font-size="11" font-family="sans-serif" fill="#365e57">${n}</text>`).join('')}<g class="${active?'map-bus':''}" tabindex="0" role="button" aria-label="Ver bus Regular B" onclick="busDetail('B',true)" onkeydown="if(event.key==='Enter')busDetail('B',true)" transform="translate(0,0)"><rect x="96" y="120" width="63" height="29" rx="8" fill="#173e50"/><text x="108" y="139" font-size="12" fill="white" font-family="sans-serif">B · 3 min</text></g></svg></div>`}
function live(){return liveRouteView()}
function stationPage(){return heading('Estación '+station,'Elige el sentido y revisa los servicios que se detienen aquí.',true)+`<div class="grid"><div class="card"><label>Estación</label><select onchange="station=this.value;render()">${stationOptions(station)}</select><div class="options spaced">${['Sur','Norte'].map(d=>`<button class="chip ${direction===d?'selected':''}" onclick="direction='${d}';render()">Sentido ${d}</button>`).join('')}</div><div class="row between spaced"><h3>Afluencia de estación</h3><span class="pill amber">Media</span></div><div class="wait"><span>Fila moderada · espera estimada</span><b>6–9 min</b></div><h3 class="spaced">Próximos buses</h3>${buses()}<button class="primary full spaced" onclick="go('live')">Ver en mapa</button></div>${mapSvg(true)}</div>`}
function busDetail(id,stops){modal(`<div class="row"><span class="bus-letter">${id}</span><h2>${id==='EX'?'Expreso':'Servicio Regular '+id}</h2></div><p>Hacia ${direction==='Sur'?'Matellini':'Naranjal'} · ${station}</p><div class="banner">${stops?'✓ Se detiene en esta estación':'Este servicio pasa sin detenerse. No puedes abordarlo aquí.'}</div><p>Llegada: ${id==='EX'?5:3} min · Ocupación ${id==='EX'?'baja':'alta'}.</p><h3>Paradas de ejemplo</h3><p>${stops?'Naranjal → Tomás Valle → UNI → Caquetá → España → Central':'Naranjal → Central (sin paradas intermedias)'}</p><p class="small">Recorrido ficticio para probar la interfaz.</p>${stops?'<button class="primary full" onclick="closeModal();origin=station;go(\'plan\')">Planificar desde aquí</button>':''}`)}
const guides=[{title:'Tu primera tarjeta',desc:'Dónde empezar y cómo prepararte para tu primer viaje.',icon:'card',tag:'PRIMEROS PASOS',time:'3 min',steps:[['Ubica un punto de atención','Consulta los canales oficiales de la ATU para localizar puntos de venta y sus horarios vigentes.'],['Revisa el costo y la forma de pago','Confirma el precio de emisión y los medios de pago antes de acercarte. No uses las tarifas simuladas de esta app como referencia.'],['Obtén y recarga tu tarjeta','Sigue las indicaciones del personal autorizado. Conserva tu comprobante y verifica el saldo.'],['Aprende a validar','Consulta la señalización del acceso y acerca tu tarjeta al lector. Espera la confirmación antes de pasar.']]},{title:'Tarjeta universitaria',desc:'Prepara tu consulta sobre el beneficio universitario.',icon:'book',tag:'VIDA UNIVERSITARIA',time:'4 min',steps:[['Confirma si te corresponde','Verifica con la ATU las condiciones actuales para acceder a la tarjeta preferencial universitaria.'],['Revisa tus documentos','Consulta qué identificación y acreditación universitaria vigente solicitan para tu caso.'],['Ubica un centro autorizado','Confirma dónde realizan la emisión o renovación y sus horarios antes de salir.'],['Consulta vigencia y uso','Pregunta por el costo, la vigencia y las condiciones del beneficio. Este prototipo no tramita tarjetas.']]},{title:'Recarga sin complicaciones',desc:'Organiza tu saldo antes de llegar a la estación.',icon:'plus',tag:'TU TARJETA',time:'2 min',steps:[['Consulta tu saldo','En un viaje real, usa un canal autorizado. El saldo de esta app es de demostración.'],['Elige un punto autorizado','Verifica los canales y métodos de recarga habilitados por el operador.'],['Verifica el resultado','Revisa el saldo y conserva el comprobante. En esta demo puedes probar el botón Recargar.']]},{title:'Elige el servicio correcto',desc:'Regulares, expresos y paradas: aprende a diferenciarlos.',icon:'route',tag:'VIAJA MEJOR',time:'3 min',steps:[['Identifica tu destino','Busca la estación donde subirás y aquella donde necesitas bajar.'],['Revisa las paradas','No todos los servicios se detienen en todas las estaciones. Confirma ambas paradas en la información oficial.'],['Verifica el sentido','Comprueba el destino del servicio y la señalización antes de abordar.'],['Considera la fila','La llegada del próximo bus no equivale al momento en el que podrás subir.']]}];
function tutorialPreview(i){const g=guides[i];return `<button class="tutorial-preview" onclick="openGuide(${i})"><span class="tile">${icon(g.icon)}</span><span><strong>${g.title}</strong><p>${g.time} de lectura · Guía práctica</p></span><span style="margin-left:auto">${icon('arrow')}</span></button>`}
function tutorials(){return heading('Aprende. Sube. Muévete.','Pequeñas guías para viajar con más confianza.')+`<div class="banner row between" style="margin-bottom:24px"><span>${icon('book')} Tu ruta de aprendizaje</span><strong>${data.done.length} de ${guides.length} completadas</strong></div><div class="tutorial-grid">${guides.map((g,i)=>`<button class="card tutorial-card" aria-label="${g.title}" onclick="openGuide(${i})"><div class="tutorial-art" style="background:${['#e5f1ec','#eaf0f7','#faf0df','#ececf5'][i]}">${icon(g.icon)}</div><article><span class="eyebrow muted">${g.tag}</span><h3 style="margin-top:10px">${g.title}</h3><p>${g.desc}</p><div class="row between"><span class="pill ${data.done.includes(i)?'green':''}">${data.done.includes(i)?'✓ Completada':g.time+' de lectura'}</span><span class="text-btn">Ver guía ${icon('arrow')}</span></div></article></button>`).join('')}</div><p class="small muted spaced">Orientación general de demostración. Confirma requisitos, precios y puntos de atención en los canales oficiales de la ATU.</p>`}
function openGuide(i){const g=guides[i];modal(`<span class="pill teal">${g.tag}</span><h2 class="spaced">${g.title}</h2><div class="timeline">${g.steps.map(([t,d],j)=>`<div class="step"><span class="step-num">${j+1}</span><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div><a href="https://www.gob.pe/atu" target="_blank" rel="noopener" class="text-btn">Consultar portal oficial de ATU ↗</a><button class="primary full" onclick="completeGuide(${i})">${data.done.includes(i)?'Guía completada':'Marcar como leída'} ${icon('check')}</button>`)}
function completeGuide(i){if(!data.done.includes(i))data.done.push(i);save();closeModal();render();toast('Progreso guardado')}
function smart(){let [h,m]=depart.split(':').map(Number),start=h*60+m,offset=Number(flex),busy=start>=17*60&&start<=19*60;let delay=busy?Math.min(offset,40):0,recommended=start+delay;const fmt=n=>String(Math.floor(n/60)%24).padStart(2,'0')+':'+String(n%60).padStart(2,'0');return heading('Que la hora punta no te apure.','Un plan de salida que también piensa en tu tiempo de estudio.')+`<div class="grid"><section class="card"><span class="pill teal">${icon('spark')} PLANIFICA TU SALIDA · DEMO</span><h2 class="spaced">¿A qué hora terminas?</h2><p class="muted">Ajusta tu disponibilidad y compara salir ahora con esperar un poco.</p><label>Salida de clases</label><input type="time" value="${depart}" onchange="depart=this.value||'18:00';render()"><label class="spaced">¿Cuánto puedes esperar?</label><select onchange="flex=this.value;render()">${[0,15,30,45,60].map(n=>`<option value="${n}" ${Number(flex)===n?'selected':''}>${n===0?'Necesito salir al terminar':n+' minutos'}</option>`).join('')}</select><label class="spaced">Estación de salida</label><select onchange="origin=this.value;render()">${stationOptions(origin)}</select><div class="notice spaced">${icon('alert')} Modelo ilustrativo con una franja de alta demanda fija. No consulta tráfico ni predice condiciones reales.</div></section><section class="card smart"><div class="row">${icon(delay?'coffee':'check')}<h3>${delay?'Aprovecha un rato más para ti':'Puedes salir al terminar'}</h3></div><div class="smart-time">Sal a las ${fmt(recommended)}</div><p>${delay?'Quédate '+delay+' min estudiando o descansando. En este escenario, la fila será más corta.':'Según tu disponibilidad, esta es la salida recomendada en la simulación.'}</p>${bars(delay?[90,85,70,48,30,25]:[30,35,28,32,24,30],Array.from({length:6},(_,i)=>fmt(start+i*10)),Math.min(5,Math.round(delay/10)))}<div class="two spaced"><div class="card"><span class="muted small">Salir ${fmt(start)}</span><h2 class="spaced">${busy?18:6} min</h2><small class="muted">de espera simulada</small></div><div class="card"><span class="muted small">Salir ${fmt(recommended)}</span><h2 class="spaced">${delay?Math.max(6,18-Math.round(delay*.3)):(busy?18:6)} min</h2><small class="muted">de espera simulada</small></div></div><p class="small">Esperar reduce tiempo en la fila, pero puede hacerte llegar más tarde. Elige según tus prioridades.</p><button class="primary full" onclick="showRoutes=false;go('plan');toast('Salida sugerida: ${fmt(recommended)} · considera este horario al planificar')">Planificar mi recorrido ${icon('arrow')}</button></section></div>`}
function notices(){const notices=[['Cierre parcial','Central: acceso norte cerrado','En este escenario, usa el acceso sur. El recorrido del servicio no cambia.','amber'],['Información de viaje','La llegada no es la espera','Un bus puede llegar en 3 minutos, pero la fila podría hacer que abordes el siguiente.','teal']];return heading('Lo que necesitas saber.','Avisos del corredor y recordatorios para tu viaje.')+`<div class="options" style="margin-bottom:24px">${[['all','Todos'],['unread','Sin leer']].map(([v,t])=>`<button class="chip ${noticeFilter===v?'selected':''}" onclick="noticeFilter='${v}';render()">${t}</button>`).join('')}</div><div class="stack">${notices.map((n,i)=>noticeFilter==='unread'&&data.read.includes(i)?'':`<section class="card"><div class="row between"><span class="pill ${n[3]}">${n[0]}</span><span class="small muted">${data.read.includes(i)?'Leído':'● Nuevo'} · Demostración</span></div><h2 class="spaced">${n[1]}</h2><p class="muted">${n[2]}</p><button class="text-btn" onclick="markRead(${i})">${data.read.includes(i)?'Marcar como no leído':'Marcar como leído'} ${icon('check')}</button></section>`).join('')}${noticeFilter==='unread'&&data.read.length===2?'<div class="card empty">Estás al día. No tienes avisos sin leer.</div>':''}</div>`}
function markRead(i){data.read=data.read.includes(i)?data.read.filter(x=>x!==i):[...data.read,i];save();render()}
function expenseChart(){const days=period==='week'?7:30;let vals=Array(days).fill(0);const today=new Date();today.setHours(0,0,0,0);for(const t of data.transactions.filter(t=>t.type==='trip')){const d=new Date(t.date);d.setHours(0,0,0,0);const ago=Math.round((today-d)/86400000);if(ago>=0&&ago<days)vals[days-1-ago]+=t.amount}let sum=vals.reduce((a,b)=>a+b,0),max=Math.max(...vals,1);return `<div class="expense-total">${money(sum)}</div><p class="muted small">${period==='week'?'Últimos 7 días':'Últimos 30 días'} · Solo viajes registrados</p><div class="chart-bars" style="height:130px;gap:${days===30?3:15}px">${vals.map((v,i)=>`<div class="chart-col selected"><i style="height:${v/max*100}%;background:${i===days-1?'#0b5aa8':'#b7d8cb'}" title="${days-1-i} días atrás: ${money(v)}"></i><span>${i===days-1?'Hoy':days===7?new Date(today.getTime()-(days-1-i)*86400000).toLocaleDateString('es-PE',{weekday:'short'}):''}</span></div>`).join('')}</div>${sum===0?'<p class="small muted">Tu gráfica crecerá cuando inicies tu primer viaje.</p>':''}`}
function profile(){return `<div class="profile-head"><span class="avatar">${esc(data.name.slice(0,2).toUpperCase())}</span><div><h1>Tu espacio, ${esc(data.name)}.</h1><p class="muted" style="margin:6px 0">Tus tarjetas y cada sol de tu recorrido.</p></div><button class="text-btn" style="margin-left:auto" onclick="editProfile()">Editar</button></div><div class="grid"><div class="stack"><section class="card"><div class="section-title"><h3>Mis tarjetas</h3><button class="text-btn" onclick="addCard()">${icon('plus')} Añadir</button></div>${wallet()}<div class="options spaced">${data.cards.map(c=>`<button class="chip ${c.id===card().id?'selected':''}" onclick="selectCard(${c.id})">${esc(c.name)}</button>`).join('')}</div><p class="small muted">Los saldos se guardan únicamente en este navegador. No están vinculados a tarjetas reales.</p></section><section class="card"><div class="section-title"><h3>Mis movimientos</h3><span class="pill">${data.transactions.length}</span></div>${data.transactions.length?data.transactions.slice(0,20).map(t=>`<div class="transaction"><span class="bus-letter">${icon(t.type==='trip'?'bus':'plus')}</span><div><strong>${esc(t.label)}</strong><p>${esc(t.card)} · ${new Date(t.date).toLocaleDateString('es-PE',{day:'numeric',month:'short'})}</p></div><strong style="color:${t.type==='trip'?'var(--ink)':'var(--teal)'}">${t.type==='trip'?'−':'+'}${money(t.amount)}</strong></div>`).join(''):'<div class="empty">Tu historial empieza con tu primer viaje o recarga.</div>'}</section></div><div class="stack"><section class="card"><div class="section-title"><h3>Así te mueves</h3><span style="color:var(--teal)">${icon('chart')}</span></div><div class="options" style="margin-bottom:20px"><button class="chip ${period==='week'?'selected':''}" onclick="period='week';render()">Semana</button><button class="chip ${period==='month'?'selected':''}" onclick="period='month';render()">Mes</button></div>${expenseChart()}<div class="row between spaced"><span class="muted small">Viajes registrados</span><strong>${data.transactions.filter(t=>t.type==='trip').length}</strong></div></section><section class="card"><div class="row">${icon('leaf')}<h3>Un viaje, menos vueltas</h3></div><p class="muted small">Prioriza recorridos directos cuando sea posible. Menos transbordos, más tiempo para ti.</p><button class="text-btn" onclick="go('plan')">Encuentra tu ruta ${icon('arrow')}</button></section><section class="card"><h3>Tu demostración</h3><p class="muted small">Puedes restaurar los saldos iniciales y borrar tus movimientos para volver a probar.</p><button class="text-btn" onclick="resetDemo()">Restablecer datos de ejemplo</button></section></div></div>`}
function modal(html){$('#modal').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section role="dialog" aria-modal="true" aria-label="Chapa tu Bus" class="dialog"><div style="display:flex;justify-content:end;margin-bottom:12px"><button class="icon-btn" aria-label="Cerrar" onclick="closeModal()">${icon('close')}</button></div>${html}</section></div>`;document.body.style.overflow='hidden';$('#modal button')?.focus()}
function closeModal(){$('#modal').innerHTML='';document.body.style.overflow=''}document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#modal .dialog')){const els=[...$('#modal').querySelectorAll('button,input,select,a[href]')];if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus()}}});
function recharge(){modal(`<h2>Un impulso a tu saldo</h2><p>Recarga de demostración para ${esc(card().name)}. No se realizará ningún cobro.</p><label for="amount">Monto en soles</label><input id="amount" type="number" min="1" max="500" step="0.50" value="10"><button class="primary full" onclick="confirmRecharge()">Añadir saldo simulado</button>`)}
function confirmRecharge(){const amount=Number($('#amount').value);if(!Number.isFinite(amount)||amount<1||amount>500)return toast('Ingresa un monto entre S/ 1 y S/ 500.');const c=card();const rounded=Math.round(amount*100)/100;c.balance=Math.round((c.balance+rounded)*100)/100;data.transactions.unshift({id:Date.now(),type:'recharge',amount:rounded,date:new Date().toISOString(),label:'Recarga simulada',card:c.name});save();closeModal();render();toast('Saldo actualizado')}
function addCard(){modal(`<h2>Una tarjeta más, todo en orden</h2><p>Añade una tarjeta de ejemplo. No ingreses un número de tarjeta real.</p><label for="cardname">Nombre</label><input id="cardname" maxlength="35" placeholder="Mi tarjeta de respaldo"><label for="cardtype">Tipo de tarjeta</label><select id="cardtype"><option>General</option><option>Universitaria</option></select><button class="primary full" onclick="confirmCard()">Crear tarjeta de ejemplo</button>`)}
function confirmCard(){const name=$('#cardname').value.trim();if(!name)return toast('Escribe un nombre para tu tarjeta.');const id=Date.now();data.cards.push({id,name,type:$('#cardtype').value,digits:String(id).slice(-4),balance:0});data.selected=id;save();closeModal();render();toast('Tarjeta añadida. Puedes recargarla para probar.')}
function editProfile(){modal(`<h2>¿Cómo te llamamos?</h2><label>Nombre de tu perfil de demostración</label><input id="username" value="${esc(data.name)}" maxlength="25"><button class="primary full" onclick="const name=$('#username').value.trim();if(!name){toast('Escribe un nombre');return}data.name=name;save();closeModal();render()">Guardar</button>`)}
function resetDemo(){modal(`<h2>¿Empezamos de nuevo?</h2><p>Se borrarán tarjetas añadidas, movimientos, progreso y viajes activos de este navegador.</p><button class="primary full" onclick="data=initial();lastRoute=null;save();closeModal();render();toast('Demostración restablecida')">Sí, restablecer demostración</button>`)}
function about(){modal(`<h2>Diseñada para probar ideas.</h2><p>Chapa tu Bus es un prototipo independiente, sin backend. Guarda tus tarjetas de ejemplo, gastos y preferencias localmente en tu navegador.</p><p>En «En vivo» y «Planificar» puedes consultar doce servicios de referencia con sus fuentes. El planificador usa sus paradas y sentidos. Incluye conexiones entre servicios del Metropolitano y recorridos dentro de cada servicio de corredor. La animación de buses, la demanda, los tiempos y las tarifas siguen siendo simulados. Los tutoriales orientan hacia la verificación oficial y no sustituyen información vigente del operador.</p><div class="banner">No realiza cobros, recargas reales ni seguimiento GPS.</div>`)}
function render(){shell();$('#app').innerHTML=({home,plan,trip,live,station:stationPage,smart,tutorials,notices,profile}[page]||home)();mountSimulation()}
render();
